  const evidenceValues = dedupe([...attrValues, ...titleValues, ...descriptionValues]);
  const conflict = attrValues.length > 1 || titleValues.length > 1 || descriptionValues.length > 1
    || (attrValues.length && titleValues.length && titleValues.some((x) => !attrValues.includes(x)))
    || (attrValues.length && descriptionValues.length && descriptionValues.some((x) => !attrValues.includes(x)));
  return { value: !conflict ? (attrValues[0] ?? titleValues[0] ?? descriptionValues[0] ?? '') : '', attrValues, titleValues, descriptionValues, evidenceValues, conflict };
