    if (/потрій|тройн/iu.test(t)) featureParts.push(ua ? 'потрійний' : 'тройной');
    else if (/складан|склад/iu.test(t) && attrAffirmative(p, /складна ручка/iu)) featureParts.push(ua ? 'складаний' : 'складной');
